package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct { // 01 TAX-REC, 13 bytes
	TrId     string          // PIC X(5) @0 len=5
	TrIncome decimal.Decimal // PIC 9(6)V99 @5 len=8
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsTax decimal.Decimal = decimal.Zero
var WsNet decimal.Decimal = decimal.Zero
var WsTotalTax decimal.Decimal = decimal.Zero
var WsCount int64 = 0
var WsIncEd string
var WsTaxEd string
var WsNetEd string
var WsTotalEd string

var taxRec TaxRec
var inputFile *os.File
var fileScanner *bufio.Scanner

var d10000 decimal.Decimal
var d40000 decimal.Decimal
var d1000 decimal.Decimal
var d7000 decimal.Decimal
var d010 decimal.Decimal
var d020 decimal.Decimal
var d030 decimal.Decimal

func mustDec(s string) decimal.Decimal {
	d, err := decimal.NewFromString(s)
	if err != nil {
		panic(err)
	}
	return d
}

func init() {
	d10000 = mustDec("10000.00")
	d40000 = mustDec("40000.00")
	d1000 = mustDec("1000.00")
	d7000 = mustDec("7000.00")
	d010 = mustDec("0.10")
	d020 = mustDec("0.20")
	d030 = mustDec("0.30")
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

// storeValue emulates COBOL numeric field store with optional rounding
// and high-order truncation.
func storeValue(v decimal.Decimal, intDigits int, scale int, rounded bool) decimal.Decimal {
	if rounded {
		v = v.Round(int32(scale))
	} else {
		v = v.Truncate(int32(scale))
	}
	neg := v.IsNegative()
	if neg {
		v = v.Neg()
	}
	s := v.StringFixed(int64(scale))
	var intPart, fracPart string
	if scale > 0 {
		parts := strings.Split(s, ".")
		intPart = parts[0]
		if len(parts) > 1 {
			fracPart = parts[1]
		} else {
			fracPart = strings.Repeat("0", scale)
		}
		if len(fracPart) < scale {
			fracPart += strings.Repeat("0", scale-len(fracPart))
		} else if len(fracPart) > scale {
			fracPart = fracPart[:scale]
		}
	} else {
		if idx := strings.Index(s, "."); idx != -1 {
			intPart = s[:idx]
		} else {
			intPart = s
		}
		fracPart = ""
	}
	if len(intPart) > intDigits {
		intPart = intPart[len(intPart)-intDigits:]
	}
	var newStr string
	if scale > 0 {
		newStr = intPart + "." + fracPart
	} else {
		newStr = intPart
	}
	d, _ := decimal.NewFromString(newStr)
	if neg {
		d = d.Neg()
	}
	return d
}

// formatDecimalEdited formats a decimal value according to a COBOL
// numeric-edited picture containing Z , . 9
func formatDecimalEdited(val decimal.Decimal, pic string) string {
	dot := strings.Index(pic, ".")
	var intPat, decPat string
	if dot != -1 {
		intPat = pic[:dot]
		decPat = pic[dot+1:]
	} else {
		intPat = pic
		decPat = ""
	}
	decDigits := len(decPat)
	intDigits := 0
	for _, ch := range intPat {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	neg := val.IsNegative()
	if neg {
		val = val.Neg()
	}
	val = val.Truncate(int32(decDigits))
	s := val.StringFixed(int64(decDigits))
	var intStr, fracStr string
	if decDigits > 0 {
		parts := strings.Split(s, ".")
		intStr = parts[0]
		if len(parts) > 1 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", decDigits)
		}
		if len(fracStr) < decDigits {
			fracStr += strings.Repeat("0", decDigits-len(fracStr))
		} else if len(fracStr) > decDigits {
			fracStr = fracStr[:decDigits]
		}
	} else {
		if idx := strings.Index(s, "."); idx != -1 {
			intStr = s[:idx]
		} else {
			intStr = s
		}
		fracStr = ""
	}
	if len(intStr) > intDigits {
		intStr = intStr[len(intStr)-intDigits:]
	}
	if len(intStr) < intDigits {
		intStr = strings.Repeat("0", intDigits-len(intStr)) + intStr
	}
	outInt := make([]byte, len(intPat))
	digitIdx := intDigits - 1
	for i := len(intPat) - 1; i >= 0; i-- {
		if intPat[i] == ',' {
			outInt[i] = ','
		} else {
			outInt[i] = intStr[digitIdx]
			digitIdx--
		}
	}
	suppressed := true
	for i := 0; i < len(intPat); i++ {
		pc := intPat[i]
		if pc == ',' {
			if suppressed {
				outInt[i] = ' '
			} else {
				outInt[i] = ','
			}
		} else if pc == 'Z' {
			if suppressed {
				if outInt[i] == '0' {
					outInt[i] = ' '
				} else {
					suppressed = false
				}
			}
		} else if pc == '9' {
			suppressed = false
		}
	}
	var result string
	if decDigits > 0 {
		result = string(outInt) + "." + fracStr
	} else {
		result = string(outInt)
	}
	if neg {
		// not needed for this program, but keep sign handling
		result = "-" + result
	}
	return result
}

func parseTaxRec(rec string) TaxRec {
	var r TaxRec
	if len(rec) < 13 {
		rec = rec + strings.Repeat(" ", 13-len(rec))
	} else if len(rec) > 13 {
		rec = rec[:13]
	}
	r.TrId = rec[0:5]
	field := rec[5:13]
	var n int64 = 0
	for i := 0; i < len(field); i++ {
		c := field[i]
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		} else {
			n = n * 10
		}
	}
	r.TrIncome = decimal.New(n, -2)
	return r
}

// READ-PARA.
func readPara() {
	if fileScanner == nil {
		WsEofFlag = "Y"
		return
	}
	if fileScanner.Scan() {
		line := fileScanner.Text()
		recStr := line
		if len(recStr) < 13 {
			recStr = recStr + strings.Repeat(" ", 13-len(recStr))
		} else if len(recStr) > 13 {
			recStr = recStr[:13]
		}
		taxRec = parseTaxRec(recStr)
	} else {
		if err := fileScanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

// PROCESS-PARA.
func processPara() {
	if taxRec.TrIncome.Cmp(d10000) <= 0 {
		raw := taxRec.TrIncome.Mul(d010)
		WsTax = storeValue(raw, 7, 2, true)
	} else {
		if taxRec.TrIncome.Cmp(d40000) <= 0 {
			diff := taxRec.TrIncome.Sub(d10000)
			raw := d1000.Add(diff.Mul(d020))
			WsTax = storeValue(raw, 7, 2, true)
		} else {
			diff := taxRec.TrIncome.Sub(d40000)
			raw := d7000.Add(diff.Mul(d030))
			WsTax = storeValue(raw, 7, 2, true)
		}
	}
	rawNet := taxRec.TrIncome.Sub(WsTax)
	WsNet = storeValue(rawNet, 7, 2, false)

	rawTotal := WsTotalTax.Add(WsTax)
	WsTotalTax = storeValue(rawTotal, 9, 2, false)

	WsCount = (WsCount + 1) % 1000

	WsIncEd = formatDecimalEdited(taxRec.TrIncome, "ZZZ,ZZ9.99")
	WsTaxEd = formatDecimalEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = formatDecimalEdited(WsNet, "ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s\n", taxRec.TrId, WsIncEd, WsTaxEd, WsNetEd)
	readPara()
}

// MAIN-PARA.
func mainPara() {
	var err error
	inputFile, err = os.Open("input.dat")
	if err != nil {
		WsEofFlag = "Y"
		fileScanner = nil
	} else {
		fileScanner = bufio.NewScanner(inputFile)
		readPara()
		for !isInputDone() {
			processPara()
		}
		inputFile.Close()
	}
	WsTotalEd = formatDecimalEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	fmt.Printf("TAXPAYERS: %03d TOTAL TAX: %s\n", WsCount, WsTotalEd)
}

func main() {
	mainPara()
}

